-- 600: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 7 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_600_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_600_guard;
INSERT INTO _migration_600_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_025' AND NOT (q.topic_id IS 'topic_igcse_chem_acids' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS '25.0 cm³ of 0.100 mol/dm³ sodium hydroxide solution exactly neutralises 20.0 cm³ of hydrochloric acid. NaOH + HCl → NaCl + H₂O. Calculate the concentration of the hydrochloric acid in mol/dm³.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '0.125 mol/dm³' AND q.explanation IS 'Moles of NaOH = 0.100 × (25.0 ÷ 1,000) = 0.00250 mol. The equation shows a 1 : 1 ratio, so moles of HCl = 0.00250 mol in 20.0 cm³. Concentration = 0.00250 ÷ (20.0 ÷ 1,000) = 0.00250 ÷ 0.0200 = 0.125 mol/dm³. Answer: 0.125 mol/dm³.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_025' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_600_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_026' AND NOT (q.topic_id IS 'topic_igcse_chem_metals' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which metal reacts steadily with cold water, producing hydrogen gas?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Copper","B. Calcium","C. Zinc","D. Iron"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Calcium reacts with cold water to give calcium hydroxide and hydrogen. (Zinc and iron react only with steam when red-hot; copper does not react with water at all.) Therefore the correct answer is B: Calcium.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_026' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_600_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_027' AND NOT (q.topic_id IS 'topic_igcse_chem_metals' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An iron nail is placed in blue copper(II) sulfate solution and a brown-pink solid forms on the nail. What is the correct explanation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Copper is more reactive than iron and dissolves the nail.","B. The nail has begun to rust.","C. Iron is more reactive than copper and displaces copper from the solution.","D. Copper(II) sulfate decomposes iron on contact."]' AND q.correct_answer IS 'C' AND q.explanation IS 'A more reactive metal displaces a less reactive one from its salt solution: Fe + CuSO₄ → FeSO₄ + Cu, and the brown-pink solid is copper. (The reactivity series puts iron above copper; rusting needs oxygen and water, not copper sulfate.) Therefore the correct answer is C: Iron is more reactive than copper and displaces copper from the solution..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_027' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_600_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_028' AND NOT (q.topic_id IS 'topic_igcse_chem_metals' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which two substances are both needed for iron to rust?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Oxygen and carbon dioxide","B. Water and salt","C. Nitrogen and water","D. Oxygen and water"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Rusting requires both oxygen and water. (Carbon dioxide and nitrogen are not involved; salt only speeds rusting up — it is not essential.) Therefore the correct answer is D: Oxygen and water.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_028' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_025', 'topic_igcse_chem_acids', 'subj_igcse_chemistry', 'igcse', NULL, NULL, '25.0 cm³ of 0.100 mol/dm³ sodium hydroxide solution exactly neutralises 20.0 cm³ of hydrochloric acid. NaOH + HCl → NaCl + H₂O. Calculate the concentration of the hydrochloric acid in mol/dm³.', 'calculation', NULL, NULL, '0.125 mol/dm³', 'Moles of NaOH = 0.100 × (25.0 ÷ 1,000) = 0.00250 mol. The equation shows a 1 : 1 ratio, so moles of HCl = 0.00250 mol in 20.0 cm³. Concentration = 0.00250 ÷ (20.0 ÷ 1,000) = 0.00250 ÷ 0.0200 = 0.125 mol/dm³. Answer: 0.125 mol/dm³.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_026', 'topic_igcse_chem_metals', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which metal reacts steadily with cold water, producing hydrogen gas?', 'multiple_choice', NULL, '["A. Copper","B. Calcium","C. Zinc","D. Iron"]', 'B', 'Calcium reacts with cold water to give calcium hydroxide and hydrogen. (Zinc and iron react only with steam when red-hot; copper does not react with water at all.) Therefore the correct answer is B: Calcium.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
