INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_028', 'topic_igcse_chem_metals', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which two substances are both needed for iron to rust?', 'multiple_choice', NULL, '["A. Oxygen and carbon dioxide","B. Water and salt","C. Nitrogen and water","D. Oxygen and water"]', 'D', 'Rusting requires both oxygen and water. (Carbon dioxide and nitrogen are not involved; salt only speeds rusting up — it is not essential.) Therefore the correct answer is D: Oxygen and water.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
